.gzp-desk{
          plano de fundo:
            gradiente radial (120% 70% a 50% 0%, rgba (214.178.110, 0,05), transparente 58%),
            gradiente radial (130% 100% a 50% 108%, rgba (0,0,0, 0,34), transparente 62%),
            /* fibra da madeira — espaçada ampla e irregularmente (linhas de cabelo antigas
               Parecia veludo) */
            gradiente linear de repetição (92 graus,
              rgba(0,0,0,.13) 0 3px,
              transparente 3px 17px,
              rgba(255.255.255,.016) 17px 20px,
              transparente 20px 41px,
              rgba(0,0,0,.09) 41px 43px,
              transparente 43px 74px),
            /* juntas das placas */
            gradiente linear de repetição (90 graus,
              rgba(0,0,0,.42) 0 2px,
              transparente 2px 148px),
            gradiente linear (180 graus, #33261a 0%, #291e13 52%, #1c150d 100%);
        }
        .gzp-under{
          posição: absoluta;
          inserção: 0;
          plano de fundo: gradiente linear (180 graus, #e6d9b6 0%, #d6c599 100%);
          box-shadow: 0 12px 22px rgba(0,0,0,.45), inserção 0 0 0 1px rgba(120,90,36,.2);
          transformar: girar (-1,15 graus) traduzirY (5px);
        }
        .gzp-under--2{
          plano de fundo: gradiente linear (180 graus, #e1d2ab 0%, #cfbd90 100%);
          transformar: girar (.85deg) traduzirY (9px);
        }
